let x = 50;
let dx = 2;

function loop() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  x += dx;
  if (x < 0 || x > canvas.width) {
    dx = -dx;
  }

  ctx.beginPath();
  ctx.arc(x, 150, 20, 0, Math.PI * 2);
  ctx.fillStyle = "orange";
  ctx.fill();

  requestAnimationFrame(loop);
}

loop();

